function validate(input) {
  const [{ Calls = [] }] = input;
  const stamp = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  const busy = new Set();
  for (const [caller, recipient, time] of Calls) {
    if (caller === null || recipient === null) return 'Every call needs a caller_id and a recipient_id.';
    if (caller === recipient) return `User ${caller} calls themself.`;
    if (!stamp.test(String(time))) return `A call of user ${caller} has a malformed call_time.`;
    for (const user of [caller, recipient]) {
      if (busy.has(`${user}|${time}`)) return `User ${user} is in two calls at ${time}.`;
      busy.add(`${user}|${time}`);
    }
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pad = n => String(n).padStart(2, '0');
  const users = small ? 5 : 150, calls = small ? Math.floor(rand() * 9) : 2000, days = small ? 2 : 20;
  // Small cases use a coarse grid with the edges of the day, so calls straddle midnight.
  const clocks = ['00:00:00', '06:30:00', '12:00:00', '18:15:00', '23:59:59'];
  const busy = new Set(), Calls = [];
  for (let attempt = 0; Calls.length < calls && attempt < calls * 20; attempt++) {
    const caller = 1 + Math.floor(rand() * users);
    let recipient = 1 + Math.floor(rand() * (users - 1));
    if (recipient >= caller) recipient++;
    const day = `2021-08-${pad(10 + Math.floor(rand() * days))}`;
    const clock = small ? clocks[Math.floor(rand() * clocks.length)]
      : `${pad(Math.floor(rand() * 24))}:${pad(Math.floor(rand() * 60))}:${pad(Math.floor(rand() * 60))}`;
    const time = `${day} ${clock}`;
    if (busy.has(`${caller}|${time}`) || busy.has(`${recipient}|${time}`)) continue;
    busy.add(`${caller}|${time}`);
    busy.add(`${recipient}|${time}`);
    Calls.push([caller, recipient, time]);
  }
  return [{ Calls }];
}
